/*
 * Static-hosting config (GitHub Pages, any file host).
 * When served by server.js this file is generated dynamically instead.
 *   static:         true  -> no server; polls and answers live inside the link
 *   googleClientId: OAuth 2.0 Web client ID to enable "Mark free times from Google Calendar"
 */
window.TA_CONFIG = window.TA_CONFIG || { static: true, googleClientId: '' };
